package com.secure.documentwallet;

import android.content.*;import android.os.Bundle;import android.text.*;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.util.*;import java.util.concurrent.*;

public class VaultSearchActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final ArrayList<JSONObject> docs=new ArrayList<>(),info=new ArrayList<>();private LinearLayout results;private TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}build();load();}
 private void build(){LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Search Results","Titles, OCR, dates, tags, and metadata"));LinearLayout command=VaultPageUi.card(this);TextView label=Ui.text(this,"WHAT ARE YOU LOOKING FOR?",11,Ui.MUTED);label.setTypeface(null,android.graphics.Typeface.BOLD);command.addView(label);EditText query=Ui.field(this,"Search titles, document text, dates…",false);query.setCompoundDrawablesWithIntrinsicBounds(android.R.drawable.ic_menu_search,0,0,0);query.setCompoundDrawablePadding(Ui.dp(this,9));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,Ui.dp(this,52));qp.topMargin=Ui.dp(this,9);command.addView(query,qp);LinearLayout filters=new LinearLayout(this);for(String name:new String[]{"All","Documents","OCR Text"}){TextView chip=Ui.text(this,name,10,Ui.TEAL);chip.setGravity(Gravity.CENTER);chip.setBackground(Ui.stroke(Ui.SOFT,Ui.dp(this,1),Ui.TEAL,Ui.dp(this,20)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-2,Ui.dp(this,32));cp.setMargins(0,Ui.dp(this,9),Ui.dp(this,6),0);filters.addView(chip,cp);}command.addView(filters);page.addView(command);status=Ui.text(this,"Opening encrypted search index…",11,Ui.MUTED);status.setPadding(Ui.dp(this,2),Ui.dp(this,15),0,Ui.dp(this,8));page.addView(status);results=Ui.column(this);page.addView(results);setContentView(VaultPageUi.scroll(this,page));query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render(s.toString());}public void afterTextChanged(Editable e){}});query.requestFocus();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void load(){io.execute(()->{try{JSONArray d=new VaultRepository(this).all(),p=new PrivateHubRepository(this).info();docs.clear();info.clear();for(int i=d.length()-1;i>=0;i--)docs.add(d.getJSONObject(i));for(int i=p.length()-1;i>=0;i--)info.add(p.getJSONObject(i));runOnUiThread(()->{status.setText((docs.size()+info.size())+" encrypted items ready to search");hint("Start typing to search without exposing your vault outside this phone.");});}catch(Exception e){runOnUiThread(()->status.setText("Could not open search index"));}});}
 private void render(String value){results.removeAllViews();String q=value.trim().toLowerCase(Locale.ROOT);if(q.isEmpty()){hint("Start typing to search without exposing your vault outside this phone.");return;}int shown=0;for(JSONObject d:docs){String hay=(d.optString("title")+" "+d.optString("category")+" "+d.optString("issuer")+" "+d.optString("documentNumber")+" "+d.optString("issueDate")+" "+d.optString("expiryDate")+" "+d.optString("tags")+" "+d.optString("notes")+" "+d.optString("searchText")).toLowerCase(Locale.ROOT);if(hay.contains(q)){LinearLayout row=VaultPageUi.row(this,"▣",d.optString("title","Document"),d.optString("category","Document")+" · Encrypted match");row.setOnClickListener(v->startActivity(new Intent(this,DocumentActivity.class).putExtra("id",d.optString("id"))));VaultPageUi.addRow(results,row);shown++;}}for(JSONObject item:info){String hay=(item.optString("title")+" "+item.optString("body")).toLowerCase(Locale.ROOT);if(hay.contains(q)){LinearLayout row=VaultPageUi.row(this,"◎",item.optString("title","Personal Information"),"Personal Information · Private match");row.setOnClickListener(v->startActivity(new Intent(this,PersonalInformationActivity.class)));VaultPageUi.addRow(results,row);shown++;}}status.setText(shown+" match"+(shown==1?"":"es")+" for “"+value.trim()+"”");if(shown==0)hint("No encrypted items match “"+value.trim()+"”.");}
 private void hint(String text){TextView hint=Ui.text(this,text,13,Ui.MUTED);hint.setGravity(Gravity.CENTER);hint.setPadding(Ui.dp(this,22),Ui.dp(this,42),Ui.dp(this,22),Ui.dp(this,42));results.addView(hint);}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
